async getLatestPrices(ids: readonly AssetId[]): Promise<LatestPrice[]> {
  const unique = [...new Set(ids.map((id) => id.value))].sort();
  const out: LatestPrice[] = [];
  for (let i = 0; i < unique.length; i += PRICE_BATCH) {
    const path = '/securities/v2/price';
    const data = await this.gateway.get<GatewayPriceResponseDto>(path, {
      query: { asset_id: unique.slice(i, i + PRICE_BATCH) },
    });
    // The day snapshot only adds open/previous close: without it the price section is still a usable answer.
    const usable =
      data && typeof data === 'object' && Array.isArray(data.price?.results)
        ? (({ error_asset_day_snapshot_v2: _ignored, ...rest }) => rest)(data as Record<string, unknown>)
        : data;
    assertNoKrakendError(usable, `GET ${path}`);
    out.push(...toLatestPrices(usable as GatewayPriceResponseDto));
  }
  return out;

export function parseGatewayTimestamp(raw: unknown): Date | null {
  const n = typeof raw === 'string' && /^\d+$/.test(raw) ? Number(raw) : raw;
  if (typeof n === 'number' && Number.isFinite(n)) {
    // Nanoseconds exceed 1e17 from 1973 on; microseconds lie between 1e14 (1973) and 1e17 (year 5138).
    if (n > 1e17) return new Date(Math.floor(n / 1e6));
    if (n > 1e14) return new Date(Math.floor(n / 1e3));
  }
  return parseTimestamp(n);
}

function readingValue(reading: GatewayPriceValueDto | null | undefined): number | null {
  return reading && typeof reading === 'object' ? toNumber(reading.value) : null;
}

function kindOf(field: unknown): LatestPriceKind {
  if (field === 'last_trade_price') return 'trade';
  if (field === 'close' || field === 'close_price') return 'close';
  return 'unknown';

/** The transactional price wins; funds have a NAV and FX rows a rate instead (ThndrApp `mapPriceToEntity`). */
function priceParts(row: GatewayPriceRowDto | undefined): PriceParts {
  const price = row?.price && typeof row.price === 'object' ? row.price : {};
  const bid = readingValue(price.bid);
  const ask = readingValue(price.ask);
  const last = readingValue(price.last);
  if (last !== null)
    return {
      last,
      kind: kindOf(price.last?.price_field),
      at: parseGatewayTimestamp(price.last?.market_effective_timestamp),
      bid,
      ask,
    };
  for (const [kind, reading] of [
    ['nav', price.nav],
    ['rate', price.rate],
  ] as const) {
    const value = readingValue(reading);
    if (value !== null)
      return { last: value, kind, at: parseGatewayTimestamp(reading?.market_effective_timestamp), bid, ask };
  }
  return { last: null, kind: 'unknown', at: null, bid, ask };

export function toLatestPrices(dto: GatewayPriceResponseDto | null | undefined): LatestPrice[] {
  const prices = new Map<string, GatewayPriceRowDto>();
  for (const row of Array.isArray(dto?.price?.results) ? dto.price.results : []) {
    if (!row || typeof row !== 'object') continue;
    const id = parseAssetIdOrNull(row.asset_id);
    if (id) prices.set(id.value, row);
  }
  const days = new Map<string, GatewayDaySideDto>();
  for (const row of Array.isArray(dto?.day_snapshot?.results) ? dto.day_snapshot.results : []) {
    if (!row || typeof row !== 'object') continue;
    const id = parseAssetIdOrNull(row.asset_id);
    if (id) days.set(id.value, daySide(row.day_snapshot?.last ?? row.day_snapshot?.rate));
  }
  const out: LatestPrice[] = [];
  for (const raw of new Set([...prices.keys(), ...days.keys()])) {
    const id = parseAssetIdOrNull(raw) as AssetId;
    const parts = priceParts(prices.get(raw));
    const day = days.get(raw) ?? {};
    const dayClose = toNumber(day.close);
    const last = parts.last ?? dayClose;
    if (last === null) continue;
    out.push(
      Object.freeze({
        instrumentId: id,
        last,
        kind: parts.last !== null ? parts.kind : 'close',
        at: parts.last !== null ? parts.at : parseGatewayTimestamp(day.market_effective_timestamp),
        open: toNumber(day.open),
        previousClose: toNumber(day.previous_close),
        bid: parts.bid,
        ask: parts.ask,
      }),
    );
  }
  return out;

export function toPosition(dto: PositionDto | null | undefined, market: Market): Position | null {
  if (!isObject(dto)) return null;
  const ticker = sanitizeTicker(dto.symbol);
  const quantity = toNumber(dto.qty);
  if (!ticker || quantity === null) return null;
  return tolerant(() =>
    createPosition({
      instrumentId: parseAssetIdOrNull(dto.asset_id),
      ticker,
      assetClass: parseAssetClass(dto.asset_class),
      currency: mapCurrency(dto.currency) ?? accountCurrency(market),
      quantity,
      averageCost: toNumber(dto.avg_cost),
      costValue: toNumber(dto.cost_value),
      marketPrice: toNumber(dto.market_price),
      unrealizedPnl: toNumber(dto.gain_loss),
      unrealizedPnlPercent: toNumber(dto.gain_loss_percentage),
      unit: stringOrNull(dto.unit),
    }),
  );

/** Maps the wallet-and-portfolio payload (§1.1). `purchase_power` is mandatory; other cash fields default to 0. */
export function toAccountSnapshot(
  dto: WalletAndPortfolioDto | null | undefined,
  market: Market,
): AccountSnapshot {
  const buyingPower = isObject(dto) ? toNumber(dto.purchase_power) : null;
  if (!isObject(dto) || buyingPower === null) {
    throw new UpstreamError('Unexpected wallet-and-portfolio payload from Thndr: missing purchase_power');
  }
  const positions = mapRows(dto.portfolio?.positions, (row) => toPosition(row, market));
  const portfolioValue =
    toNumber(dto.portfolio?.portfolio_value) ?? positions.reduce((sum, p) => sum + (p.marketValue ?? 0), 0);
  const summary = createAccountSummary({
    buyingPower,
    blockedCash: toNumber(dto.cash_in_holding) ?? 0,
    unsettledCash: toNumber(dto.unsettled_cash) ?? 0,
    settledCash: toNumber(dto.settled_cash),
    portfolioValue,
    totalReturn: toNumber(dto.portfolio?.total_return),
    totalReturnPercent: toNumber(dto.portfolio?.total_return_prc),
    currency: accountCurrency(market),
  });
  return Object.freeze({ summary, positions: Object.freeze(positions) });

### Bounded contexts and context map

| Context | Role | Upstream dependencies |
| --- | --- | --- |
| Identity & Access | Generic subdomain: login, device approval, session | none (consumed by repositories through the `AccessTokenProvider` port) |
| Market Data | Core, upstream **supplier** (Open Host Service: `application/market-data/services/*` and its domain types as published language) | none |
| Portfolio | Core, **customer** of Market Data | Market Data |
| Engagement | Supporting, **customer** of Market Data | Market Data |

- **Shared Kernel** (`domain/shared-kernel/`): `Money`, `Ticker`, `AssetId`, `Market`, domain errors and guards. It is
  shared by every context and depends on nothing.
- No context depends on Portfolio or Engagement. Portfolio and Engagement never depend on each other or on Identity.

### Enforcement

`src/__tests__/architecture.test.ts` turns these rules into build failures:

- the layer matrix;
- allowed packages per layer;
- the context map, including published-interface-only access;
- the shared kernel's independence;
- one `Query`/`Command` per file in `queries/`/`commands/`;
- no use case importing another;
- no use cases in presentation.

